// Package generator generates CLI bindings from unary RPC descriptors.
package generator

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode"

	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/reflect/protoreflect"
)

const (
	runtimePath = protogen.GoImportPath("github.com/sir-hassan/inframill/internal/cli/runtime")
	cobraPath   = protogen.GoImportPath("github.com/spf13/cobra")
	protoPath   = protogen.GoImportPath("google.golang.org/protobuf/proto")
	contextPath = protogen.GoImportPath("context")
	connectPath = protogen.GoImportPath("connectrpc.com/connect")
)

func words(name string) []string {
	var parts []string
	letters := []rune(name)
	start := 0
	for i, r := range letters {
		if i > 0 && unicode.IsUpper(r) && (!unicode.IsUpper(letters[i-1]) || (i+1 < len(letters) && unicode.IsLower(letters[i+1]))) {
			parts = append(parts, strings.ToLower(string(letters[start:i])))
			start = i
		}
	}
	return append(parts, strings.ToLower(string(letters[start:])))
}

func path(method *protogen.Method) (string, string, error) {
	parts := words(method.GoName)
	if len(parts) < 2 {
		return "", "", fmt.Errorf("method %s requires VerbResource naming", method.GoName)
	}
	resource := strings.Join(parts[1:], "-")
	if parts[0] == listVerb {
		if !strings.HasSuffix(resource, "s") {
			return "", "", fmt.Errorf("list method %s requires a plural resource", method.GoName)
		}
		resource = strings.TrimSuffix(resource, "s")
	}
	return resource, parts[0], nil
}

type binding struct {
	method         *protogen.Method
	group, name    string
	connectPackage protogen.GoImportPath
	client         string
}

func Generate(plugin *protogen.Plugin) error {
	var bindings []binding
	paths := map[string]bool{}
	for _, file := range plugin.Files {
		if !file.Generate {
			continue
		}
		for _, service := range file.Services {
			if service.GoName != "EngineService" {
				return fmt.Errorf("unsupported service %s: CLI runtime uses EngineServiceClient", service.GoName)
			}
			connectPackage := protogen.GoImportPath(string(file.GoImportPath) + "/" + string(file.GoPackageName) + "connect")
			for _, method := range service.Methods {
				if method.Desc.IsStreamingClient() || method.Desc.IsStreamingServer() {
					return fmt.Errorf("streaming method %s is unsupported", method.GoName)
				}
				if err := validate(method); err != nil {
					return err
				}
				group, name, err := path(method)
				if err != nil {
					return err
				}
				// SPEC-0007: Driver health uses native Engine composition, like exec.
				// Keep transport generation but reserve its CLI path for the native leaf.
				if method.GoName == "ListDrivers" {
					continue
				}
				variants := []string{name}
				switch method.GoName {
				case "SubmitCommand":
					group = "instance"
					variants = []string{"exec", "delete"}
				case "ReadCommandLog":
					group = "command execution"
					variants = []string{"stdout", "stderr"}
				case "ListBlueprints":
					variants = []string{listVerb, "show"}
				case "ListCommandDefinitions":
					group = "command"
					variants = []string{listVerb, "show"}
				case "ListCommandExecutions":
					group = "command execution"
				case "GetCommandExecution":
					group = "command execution"
					variants = []string{"get", "wait"}
				}
				for _, variant := range variants {
					key := group + " " + variant
					if paths[key] {
						return fmt.Errorf("command collision: %s", key)
					}
					paths[key] = true
					bindings = append(bindings, binding{method, group, variant, connectPackage, service.GoName + "Client"})
				}
			}
		}
	}
	sort.Slice(bindings, func(i, j int) bool {
		return bindings[i].group+" "+bindings[i].name < bindings[j].group+" "+bindings[j].name
	})
	if len(bindings) == 0 {
		return nil
	}
	g := plugin.NewGeneratedFile("commands.gen.go", "github.com/sir-hassan/inframill/internal/cli/gen")
	g.P("// Code generated by protoc-gen-inframill-cli. DO NOT EDIT.")
	g.P("package gen")
	g.P("func Register(root *", cobraPath.Ident("Command"), ", runner *", runtimePath.Ident("Runtime"), ") {")
	for i, b := range bindings {
		g.P("runner.Add(root,", strconv.Quote(b.group), ", command", i, "(runner))")
	}
	g.P("}")
	for i, b := range bindings {
		emit(g, i, b)
	}
	return nil
}

func validate(method *protogen.Method) error {
	seen := map[string]bool{"help": true, "color": true, "output": true, "endpoint": true, "timeout": true, "config": true, "columns": true, "wait": true, "confirm": true, "pager": true, "pager-arg": true}
	for _, f := range method.Input.Fields {
		if f.Desc.IsList() || f.Desc.IsMap() || f.Oneof != nil {
			return fmt.Errorf("%s.%s: repeated/map/oneof requests are unsupported", method.GoName, f.Desc.Name())
		}
		name := strings.ReplaceAll(string(f.Desc.Name()), "_", "-")
		if f.Message != nil {
			name = fileFlag(method.GoName, name)
		}
		if seen[name] {
			return fmt.Errorf("%s: reserved or colliding flag %s", method.GoName, name)
		}
		seen[name] = true

		//nolint:exhaustive // Unsupported descriptor kinds reject in the default branch.
		switch f.Desc.Kind() {
		case protoreflect.StringKind, protoreflect.BoolKind, protoreflect.Int32Kind, protoreflect.Int64Kind, protoreflect.Uint32Kind, protoreflect.Uint64Kind, protoreflect.FloatKind, protoreflect.DoubleKind, protoreflect.EnumKind, protoreflect.MessageKind:
		default:
			return fmt.Errorf("%s.%s: unsupported request kind %s", method.GoName, f.Desc.Name(), f.Desc.Kind())
		}
	}
	return nil
}

func emit(g *protogen.GeneratedFile, index int, b binding) {
	method := b.method
	g.P("func command", index, "(runner *", runtimePath.Ident("Runtime"), ") *", cobraPath.Ident("Command"), " {")
	g.P("request := &", method.Input.GoIdent, "{}")
	g.P("response := &", method.Output.GoIdent, "{}")
	short := strings.TrimSpace(string(method.Comments.Leading))
	if short == "" {
		short = method.GoName + " through the daemon"
	}
	g.P("cmd := &", cobraPath.Ident("Command"), "{Use:", strconv.Quote(b.name), ", Short:", strconv.Quote(short), ", Example:", strconv.Quote("  inframill "+b.group+" "+b.name+" --help"), "}")
	g.P(runtimePath.Ident("Configure"), "(cmd, request)")
	for _, f := range method.Input.Fields {
		if adaptedField(method.GoName, b.name, string(f.Desc.Name())) {
			continue
		}
		name := strings.ReplaceAll(string(f.Desc.Name()), "_", "-")
		help := strings.TrimSpace(string(f.Comments.Leading))
		if help == "" {
			help = "request " + strings.ReplaceAll(name, "-", " ")
		}
		if f.Message != nil {
			g.P("var file", f.GoName, " string")
			g.P("cmd.Flags().StringVar(&file", f.GoName, ",", strconv.Quote(fileFlag(method.GoName, name)), ",\"\",", strconv.Quote(help+" JSON file, or - for stdin"), ")")
			continue
		}
		if f.Enum != nil {
			labels := map[string]int32{}
			prefix := strings.TrimSuffix(string(f.Enum.Values[0].Desc.Name()), "UNSPECIFIED")
			for _, v := range f.Enum.Values {
				if v.Desc.Number() == 0 {
					continue
				}
				labels[strings.ToLower(string(v.Desc.Name()))] = int32(v.Desc.Number())
				labels[strings.ToLower(strings.TrimPrefix(string(v.Desc.Name()), prefix))] = int32(v.Desc.Number())
			}
			keys := make([]string, 0, len(labels))
			for key := range labels {
				keys = append(keys, key)
			}
			sort.Strings(keys)
			g.P(runtimePath.Ident("Enum"), "(cmd.Flags(),", strconv.Quote(name), ",", strconv.Quote(help), ", map[string]int32{")
			for _, key := range keys {
				g.P(strconv.Quote(key), ":", labels[key], ",")
			}
			g.P("},func(v int32){request.", f.GoName, "=", f.Enum.GoIdent, "(v)})")
			g.P("_ = cmd.RegisterFlagCompletionFunc(", strconv.Quote(name), ",", cobraPath.Ident("FixedCompletions"), "([]string{")
			for _, key := range keys {
				if !strings.HasPrefix(key, strings.ToLower(prefix)) {
					g.P(strconv.Quote(key), ",")
				}
			}
			g.P("},", cobraPath.Ident("ShellCompDirectiveNoFileComp"), "))")
			continue
		}

		//nolint:exhaustive // Only validated scalar kinds reach this emission branch.
		kind := map[protoreflect.Kind]string{protoreflect.StringKind: "String", protoreflect.BoolKind: "Bool", protoreflect.Int32Kind: "Int32", protoreflect.Int64Kind: "Int64", protoreflect.Uint32Kind: "Uint32", protoreflect.Uint64Kind: "Uint64", protoreflect.FloatKind: "Float32", protoreflect.DoubleKind: "Float64"}[f.Desc.Kind()]
		g.P("cmd.Flags().", kind, "Var(&request.", f.GoName, ",", strconv.Quote(name), ", request.", f.GoName, ",", strconv.Quote(help), ")")
	}
	if b.name == listVerb {
		g.P("cmd.Flags().String(\"columns\",\"\",\"comma-separated column keys in display order\")")
	}
	g.P("cmd.RunE = func(cmd *", cobraPath.Ident("Command"), ",args []string)error {")
	g.P("return runner.Execute(cmd,args,request,response,func()error {")
	for _, f := range method.Input.Fields {
		if adaptedField(method.GoName, b.name, string(f.Desc.Name())) {
			continue
		}
		if f.Message != nil {
			g.P("if file", f.GoName, " != \"\" { request.", f.GoName, "=&", f.Message.GoIdent, "{}; if err:=", runtimePath.Ident("ReadJSON"), "(file", f.GoName, ",runner.Stdin,request.", f.GoName, ");err!=nil{return err} }")
		}
	}
	g.P("return nil },func(ctx ", contextPath.Ident("Context"), ",client ", b.connectPackage.Ident(b.client), ")(", protoPath.Ident("Message"), ",error){")
	g.P("result,err:=client.", method.GoName, "(ctx,", connectPath.Ident("NewRequest"), "(request));if err!=nil{return nil,err};return result.Msg,nil")
	g.P("}) }")
	g.P("return cmd }")
}

const (
	listVerb = "list"
)

// adaptedField excludes only fields supplied by the typed positional/constant adapters.
func adaptedField(method, variant, field string) bool {
	switch method {
	case "FetchBlueprint":
		return field == "reference"
	case "InitInstance":
		return field == "name"
	case "GetInstance":
		return field == instanceIDField
	case "GetCommandExecution":
		return field == instanceIDField || field == "command_id"
	case "SubmitCommand":
		return field == instanceIDField || field == "command" || (variant == "delete" && field == "args")
	case "ReadCommandLog":
		return field == instanceIDField || field == "command_id" || field == "stream"
	default:
		return false
	}
}

const (
	instanceIDField = "instance_id"
)

func fileFlag(method, field string) string {
	if method == "InitInstance" && field == "instance" {
		return "file"
	}
	return field + "-file"
}
